const STOP = new Set(("a an and are as at be but by can could do does for from had has have how i in is it me my of on or please tell the this to was we what when where which who why with would you your de des du la le les un une et est je tu vous votre mon ma mes pour dans comment que qui quoi au aux en ce cette ces sur avec ou il elle sont peut pouvez aider expliquez explique moi هل من في ما كيف ماذا عن إلى على هذا هذه هو هي أنا أنت لي فضلك").split(/\s+/));
function tokens(value: string): string[] { return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[’']/g," ").replace(/[^\p{L}\p{N}\s]/gu," ").split(/\s+/).filter(t=>t.length>1&&!STOP.has(t)).map(t=>t.replace(/(ing|ed|es|s)$/,"")); }
export function matchChatExample(value: string): {intent:string;canonical:string;score:number}|null { const query=[...new Set(tokens(value))]; if(query.length<2)return null; let best:any=null,second=0; for(const example of CHAT_EXAMPLES){const candidate=[...new Set(tokens(example.utterance))];const shared=query.filter(t=>candidate.includes(t));if(shared.length<2)continue;const score=shared.reduce((sum,t)=>sum+(t.length>=6?1.15:1),0)/Math.max(3,query.length);if(!best||score>best.score){second=best?.score||second;best={intent:example.intent,canonical:example.canonical,score}}else if(example.intent!==best.intent&&score>second)second=score;}if(!best||best.score<0.56||best.score-second<0.06)return null;return best; }
